// Claude's review tests for A39 (request headers on real calls) in the page and the panel.
// agy: do not edit this file.
import { expect, test, type Page } from '@playwright/test';
import { emptyState, type HeaderRule, type Mock, type Project, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

const rule = (id: string, extra: Partial<HeaderRule> = {}): HeaderRule => ({
  id, enabled: true, method: 'ANY', urlPattern: '/api/*rest', name: 'Authorization', value: 'Bearer t', ...extra,
});

async function readState(): Promise<WemockState> {
  return session.worker.evaluate(async () => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    return (await (globalThis as any).chrome.storage.local.get('wemock.state'))['wemock.state'];
  });
}

async function open(rules: HeaderRule[], mocks: Mock[] = []): Promise<{ page: Page; panel: Page }> {
  const p: Project = { id: 'p1', name: 'site', origins: [fixture.origin], activeScenarioId: 'default', scenarios: [{ id: 'default', name: 'Default', mocks }], headerRules: rules };
  await session.setState({ ...emptyState(), enabledOrigins: [fixture.origin], projects: [p] });
  const page = await session.context.newPage();
  await page.goto(`${fixture.url}/index.html`);
  const tabId = await session.tabIdOf(page);
  const panel = await session.context.newPage();
  await panel.goto(`chrome-extension://${session.extensionId}/panel.html?tabId=${tabId}`);
  return { page, panel };
}

// /api/headers on the fixture answers with the request headers it received, names lower-cased.
const sent = (page: Page) => page.evaluate(async () => {
  const viaFetch = await (await fetch('/api/headers', { headers: { 'X-Debug': '1', Authorization: 'old' } })).json();
  const viaRequest = await (await fetch(new Request('/api/headers', { headers: { 'X-Debug': '1' } }))).json();
  const viaXhr = await new Promise<Record<string, string>>((resolve) => {
    const x = new XMLHttpRequest();
    x.open('GET', '/api/headers');
    x.setRequestHeader('X-Debug', '1');
    x.setRequestHeader('Authorization', 'old');
    x.onload = () => resolve(JSON.parse(x.responseText));
    x.send();
  });
  return { viaFetch, viaRequest, viaXhr };
});

test('rules set and remove headers on real fetch, Request and XHR calls', async () => {
  const { page, panel } = await open([rule('auth'), rule('nodebug', { name: 'X-Debug', value: '' })]);
  try {
    const got = await sent(page);
    for (const h of [got.viaFetch, got.viaRequest, got.viaXhr]) {
      expect(h['authorization']).toBe('Bearer t');
      expect(h['x-debug']).toBeUndefined();
    }
  } finally {
    await panel.close();
    await page.close();
  }
});

test('a rule that is off, or for another path, changes nothing; mocked calls are untouched', async () => {
  const echo: Mock = { id: 'm', name: 'm', enabled: true, method: 'GET', urlPattern: '/api/mocked', reply: 'code', code: 'return req.headers;', source: 'manual', createdAt: 0,
    response: { status: 200, headers: { 'content-type': 'application/json' }, body: '', bodyEncoding: 'text', delayMs: 0 } };
  const { page, panel } = await open([rule('off', { enabled: false }), rule('other', { urlPattern: '/elsewhere/*rest', name: 'X-Other', value: '1' }), rule('auth', { urlPattern: '/api/mocked' })], [echo]);
  try {
    const got = await sent(page);
    expect(got.viaFetch['authorization']).toBe('old');
    expect(got.viaFetch['x-debug']).toBe('1');
    expect(got.viaFetch['x-other']).toBeUndefined();
    const mocked = await page.evaluate(async () => (await fetch('/api/mocked', { headers: { Authorization: 'page' } })).json());
    expect(JSON.stringify(mocked).toLowerCase()).toContain('page');
    expect(JSON.stringify(mocked)).not.toContain('Bearer t');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the Log shows the request headers sent, marking the changed ones', async () => {
  const { page, panel } = await open([rule('auth')]);
  try {
    await page.evaluate(async () => (await fetch('/api/headers', { headers: { 'X-Keep': 'k' } })).text());
    await panel.getByTestId('log-row').filter({ hasText: '/api/headers' }).first().click();
    const req = panel.getByTestId('request-headers');
    await expect(req).toContainText('x-keep: k');
    await expect(req).toContainText('authorization: Bearer t');
    await expect(req.getByTestId('request-header-changed')).toHaveCount(1);
    await expect(req.getByTestId('request-header-changed')).toContainText('authorization');

    // XHR calls show what was sent too.
    await page.evaluate(() => new Promise<void>((resolve) => {
      const x = new XMLHttpRequest();
      x.open('GET', '/api/headers');
      x.setRequestHeader('X-Keep', 'x');
      x.onloadend = () => resolve();
      x.send();
    }));
    const rows = panel.getByTestId('log-row').filter({ hasText: '/api/headers' });
    await expect(rows).toHaveCount(2);
    await rows.last().click();
    const xreq = panel.getByTestId('request-headers');
    await expect(xreq).toContainText('x-keep: x');
    await expect(xreq.getByTestId('request-header-changed')).toContainText('authorization');

    // A blob XHR is reported from its own code path.
    await page.evaluate(() => new Promise<void>((resolve) => {
      const x = new XMLHttpRequest();
      x.open('GET', '/api/headers');
      x.responseType = 'blob';
      x.setRequestHeader('X-Keep', 'blob');
      x.onloadend = () => resolve();
      x.send();
    }));
    await expect(rows).toHaveCount(3);
    await rows.last().click();
    await expect(panel.getByTestId('request-headers')).toContainText('x-keep: blob');
  } finally {
    await panel.close();
    await page.close();
  }
});

test('the Mocks tab edits rules; a forbidden name is refused; changes save at once', async () => {
  const { page, panel } = await open([]);
  try {
    await panel.getByTestId('tab-mocks').click();
    await panel.getByTestId('hrule-add').click();
    const row = panel.getByTestId('hrule-row').first();
    await row.getByTestId('hrule-pattern').fill('/api/*rest');
    await row.getByTestId('hrule-name').fill('Cookie');
    await expect(row.getByTestId('hrule-error')).toHaveText('Browsers do not let pages set Cookie');
    await row.getByTestId('hrule-name').fill('X-Feature');
    await row.getByTestId('hrule-value').fill('beta');
    await expect(row.getByTestId('hrule-error')).toHaveCount(0);
    await expect.poll(async () => (await readState()).projects[0]!.headerRules).toMatchObject([{ enabled: true, method: 'ANY', urlPattern: '/api/*rest', name: 'X-Feature', value: 'beta' }]);
    await page.reload();
    expect((await page.evaluate(async () => (await fetch('/api/headers')).json()))['x-feature']).toBe('beta');
    await row.getByTestId('hrule-enabled').uncheck();
    await expect.poll(async () => (await readState()).projects[0]!.headerRules![0]!.enabled).toBe(false);
    await row.getByTestId('hrule-remove').click();
    await expect.poll(async () => (await readState()).projects[0]!.headerRules ?? []).toEqual([]);
  } finally {
    await panel.close();
    await page.close();
  }
});
